mkdir -p src/viz-widget && cat > src/viz-widget/chartkit-setup.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';

/**
 * Registers chart engines in the ChartKit plugin registry.
 *
 * Both plugins are declared here, but each plugin's `renderer` is a `React.lazy` component:
 * `@gravity-ui/charts` is fetched only when the widget first renders `type="gravity-charts"`,
 * `@gravity-ui/yagr` only when it first renders `type="yagr"`. Registering is cheap — it does
 * not download either engine.
 *
 * Call once at the app entry point, before any `<VizWidget>` mounts.
 */
export function setupChartKit(lang: 'ru' | 'en' = 'ru') {
    settings.set({plugins: [GravityChartsPlugin, YagrPlugin], lang});
}
EOF
cat > src/viz-widget/types.ts <<'EOF'
/** Rendering mode of the widget. Each mode maps to its own chart engine. */
export type VizMode = 'sales' | 'monitoring';

/** One point of a regular business series (sales chart). */
export interface SalesPoint {
    /** Unix timestamp in milliseconds. */
    x: number;
    y: number;
}

export interface SalesSeries {
    name: string;
    data: SalesPoint[];
}

/** Dense time series: a shared timeline plus one value array per metric. */
export interface MonitoringSeries {
    name: string;
    /** Same length as `timeline`; `null` is a gap. */
    values: Array<number | null>;
}

export interface SalesDataset {
    series: SalesSeries[];
    /** Unit shown in tooltip, e.g. "₽". */
    unit?: string;
}

export interface MonitoringDataset {
    /** Unix timestamps in milliseconds, ascending. */
    timeline: number[];
    series: MonitoringSeries[];
    /** Unit shown on the Y axis and in tooltip, e.g. "ms" or "%". */
    unit?: string;
}

/** Unified data contract for both modes. */
export interface VizWidgetData {
    sales: SalesDataset;
    monitoring: MonitoringDataset;
}
EOF
cat > src/viz-widget/adapters.ts <<'EOF'
import type {ChartData} from '@gravity-ui/charts';
import type {YagrWidgetData} from '@gravity-ui/chartkit/yagr';

import type {MonitoringDataset, SalesDataset} from './types';

/**
 * Adapts the widget's sales dataset to the declarative `@gravity-ui/charts` config
 * consumed by the `gravity-charts` ChartKit plugin.
 */
export function toGravityChartsData(dataset: SalesDataset): ChartData {
    const unit = dataset.unit ? ` ${dataset.unit}` : '';

    return {
        series: {
            data: dataset.series.map((s) => ({
                type: 'line',
                name: s.name,
                lineWidth: 2,
                marker: {enabled: false},
                data: s.data.map((p) => ({x: p.x, y: p.y})),
            })),
        },
        xAxis: {
            type: 'datetime',
        },
        yAxis: [
            {
                labels: {
                    numberFormat: {type: 'number', showRankDelimiter: true, postfix: unit},
                },
            },
        ],
        legend: {
            // A single series needs no legend: the widget title names it.
            enabled: dataset.series.length > 1,
            position: 'bottom',
        },
        tooltip: {
            headerFormat: {type: 'date', format: 'DD MMM YYYY'},
            valueFormat: {type: 'number', showRankDelimiter: true, postfix: unit},
        },
    };
}

/**
 * Adapts the widget's monitoring dataset to `YagrWidgetData` consumed by the `yagr`
 * ChartKit plugin (canvas renderer built for dense realtime series).
 */
export function toYagrData(dataset: MonitoringDataset): YagrWidgetData {
    const unit = dataset.unit ?? '';

    return {
        data: {
